def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    dangerous_prev = []
    weak_count = 0
    rich_count = 0

    for opp in alive:
        if opp.get('budget', 0) >= 120:
            rich_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            weak_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            if opp.get('budget', 0) >= bid * 0.6:
                dangerous_prev.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    effective_high = max(dangerous_prev) if dangerous_prev else highest_prev

    scarcity = (25.0 - supply) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.6
    elif no_water_days == 1:
        urgency += 0.25
    urgency += scarcity * 0.35

    if supply >= 23:
        base = DAILY_SALARY * 0.22
    elif supply >= 20:
        base = DAILY_SALARY * 0.34
    elif supply >= 17:
        base = DAILY_SALARY * 0.52
    else:
        base = DAILY_SALARY * 0.72

    if day >= 8:
        base += 6

    if effective_high >= 180:
        if urgency < 0.55:
            target = base * 0.75
        else:
            target = min(effective_high * 0.72, DAILY_SALARY * 1.28)
    elif effective_high >= 110:
        if urgency < 0.45:
            target = max(base, effective_high * 0.55)
        else:
            target = min(effective_high + 3.0, DAILY_SALARY * 1.22)
    elif effective_high > 0:
        target = max(base, effective_high + 2.0)
    else:
        target = base

    if weak_count >= 2 and urgency < 0.6:
        target *= 0.88
    if rich_count >= 2 and supply <= 18:
        target *= 1.08

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water_days == 1:
        target = max(target, DAILY_SALARY * 0.62)

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 0.35
    max_today = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_today = budget

    bid = min(target, max_today)
    if bid < 0:
        bid = 0.0
    if budget < DAILY_SALARY * 0.18 and (hp <= 3 or no_water_days >= 1):
        bid = budget

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0

    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    # base_factor based on supply
    if supply <= 18:
        base_factor = 0.85
    elif supply <= 22:
        base_factor = 0.65
    else:
        base_factor = 0.5

    base_bid = DAILY_SALARY * base_factor

    if max_yesterday_bid > 0:
        if max_yesterday_bid > DAILY_SALARY * 0.8:
            if hp <= 3:
                target_bid = min(budget, max_yesterday_bid * 1.1)
            else:
                target_bid = min(budget, max_yesterday_bid * 0.8)
        else:
            target_bid = min(budget, max_yesterday_bid + 5)
    else:
        target_bid = base_bid

    bid = min(budget, target_bid)

    # urgency adjustments for late days or low hp
    if day > 5 and hp <= 4:
        bid = min(budget, bid * 1.3)
    if day > 8 and hp <= 2:
        bid = min(budget, bid * 1.5)

    # must get water if critically low
    if no_water >= 1 and hp <= 3:
        bid = max(bid, min(budget, DAILY_SALARY * 0.7))

    # conserve if healthy and bid is high
    if hp > 6 and bid > DAILY_SALARY * 0.4:
        bid = min(bid, DAILY_SALARY * 0.3)

    return float(max(0, bid))
